CREATE TABLE IF NOT EXISTS invitations (digest TEXT PRIMARY KEY, id TEXT UNIQUE NOT NULL, expires INTEGER NOT NULL, used TEXT, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (digest TEXT PRIMARY KEY, id TEXT UNIQUE NOT NULL, role TEXT NOT NULL, expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS policy (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS owner_config (id INTEGER PRIMARY KEY CHECK(id=1), digest TEXT NOT NULL);
